    ref('T4','Theorem 3 — qualified estimator','estimator_reference','Only the upper-bound estimator clause refers to the rank/loss/TRIP qualification D30. The lower minimax branch remains distinct.')
    for n in [2,5,6,8]:ref('T'+str(n),'Theorem 1 — lambda definition','object_reference','The least true-rank singular-value signal definition is used without importing the additional RGD assumptions.')
